mapper.select:
SELECT COUNT(*)
FROM forum_posts
WHERE deleted_at IS NULL AND status=#{status}

SELECT p.*,u.nickname,u.avatar_resource_id,
(SELECT COUNT(*) FROM forum_interactions i WHERE i.post_id=p.id AND i.kind='likes') AS like_count,
(SELECT COUNT(*) FROM forum_interactions i WHERE i.post_id=p.id AND i.kind='favorites') AS favorite_count
FROM forum_posts p
JOIN forum_users u ON u.id=p.author_id
WHERE p.deleted_at IS NULL AND p.status=#{status}
ORDER BY p.submitted_atp.first_published_at DESC,p.id DESC
LIMIT #{size}
OFFSET #{offset}

mapper.update:
UPDATE forum_posts
SET status=#{status},
first_published_at=CASE WHEN #{status}='PUBLISHED' THEN COALESCE(first_published_at,#{publishedAt}) ELSE first_published_at END,
rejection_reason=#{reason},reviewed_by=#{reviewerId},reviewed_at=#{reviewedAt}
WHERE id=#{id}

UPDATE forum_posts
SET deleted_at=#{deletedAt}
WHERE id=#{id}
